{
  "imports": [
    "from decimal import Decimal",
    "from ledger.rounding import cash_round"
  ],
  "tests": [
    {
      "name": "test_cash_round_bug_1_03_rounds_to_1_05",
      "intent": "the bug: 1.03 should round to nearest 0.05, which is 1.05",
      "code": "# intent: the bug: 1.03 should round to nearest 0.05, which is 1.05\ndef test_cash_round_bug_1_03_rounds_to_1_05():\n    assert cash_round(Decimal('1.03')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_exact_half_rounds_up",
      "intent": "exact half (1.025) rounds up to 1.05",
      "code": "# intent: exact half (1.025) rounds up to 1.05\ndef test_cash_round_exact_half_rounds_up():\n    assert cash_round(Decimal('1.025')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_just_below_half_rounds_down",
      "intent": "value just below half (1.024) rounds down to 1.00",
      "code": "# intent: value just below half (1.024) rounds down to 1.00\ndef test_cash_round_just_below_half_rounds_down():\n    assert cash_round(Decimal('1.024')) == Decimal('1.00')\n"
    },
    {
      "name": "test_cash_round_just_above_half_rounds_up",
      "intent": "value just above half (1.026) rounds up to 1.05",
      "code": "# intent: value just above half (1.026) rounds up to 1.05\ndef test_cash_round_just_above_half_rounds_up():\n    assert cash_round(Decimal('1.026')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_exact_multiple_unchanged",
      "intent": "exact multiple of step (1.05) remains unchanged",
      "code": "# intent: exact multiple of step (1.05) remains unchanged\ndef test_cash_round_exact_multiple_unchanged():\n    assert cash_round(Decimal('1.05')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_custom_step",
      "intent": "custom step (0.10) works: 2.25 rounds to 2.30",
      "code": "# intent: custom step (0.10) works: 2.25 rounds to 2.30\ndef test_cash_round_custom_step():\n    assert cash_round(Decimal('2.25'), Decimal('0.10')) == Decimal('2.30')\n"
    }
  ]
}
